const colors = [
    { name: "rot",     hue: 0,   saturation: 100 },
    { name: "orange",  hue: 30,  saturation: 100 },
    { name: "gelb",    hue: 60,  saturation: 100 },
    { name: "gruen",   hue: 120, saturation: 100 },
    { name: "cyan",    hue: 180, saturation: 100 },
    { name: "blau",    hue: 240, saturation: 100 },
    { name: "violett", hue: 280, saturation: 100 },
    { name: "pink",    hue: 320, saturation: 100 }
];

let index = flow.get("lamp_color_index") || 0;
let color = colors[index];

msg.topic = "zigbee2mqtt/lampe/set";
msg.payload = {
    state: "ON",
    brightness: 180,
    color: {
        hue: color.hue,
        saturation: color.saturation
    },
    transition: 1
};

node.status({
    fill: "blue",
    shape: "dot",
    text: color.name
});

flow.set("lamp_color_index", (index + 1) % colors.length);
return msg;

const cmd = msg.payload && msg.payload.cmd;

const rainbow = [
    { name: "rot",     hue: 0,   saturation: 100 },
    { name: "orange",  hue: 30,  saturation: 100 },
    { name: "gelb",    hue: 60,  saturation: 100 },
    { name: "gruen",   hue: 120, saturation: 100 },
    { name: "cyan",    hue: 180, saturation: 100 },
    { name: "blau",    hue: 240, saturation: 100 },
    { name: "violett", hue: 280, saturation: 100 },
    { name: "pink",    hue: 320, saturation: 100 }
];

function sendColor(name, hue, saturation, brightness, transition = 1) {
    msg.payload = {
        state: "ON",
        brightness: brightness,
        color: {
            hue: hue,
            saturation: saturation
        },
        transition: transition
    };
    node.status({ fill: "blue", shape: "dot", text: name });
    return msg;
}

function sendWhite(name, colorTemp, brightness, transition = 1) {
    msg.payload = {
        state: "ON",
        brightness: brightness,
        color_temp: colorTemp,
        transition: transition
    };
    node.status({ fill: "yellow", shape: "dot", text: name });
    return msg;
}

if (cmd === "rainbow_start") {
    flow.set("rainbow_running", true);
    flow.set("rainbow_index", 0);
    const c = rainbow[0];
    return sendColor("Rainbow: " + c.name, c.hue, c.saturation, 180, 1);
}

if (cmd === "rainbow_stop") {
    flow.set("rainbow_running", false);
    node.status({ fill: "grey", shape: "ring", text: "Rainbow aus" });
    return null;
}

if (cmd === "rainbow_tick") {
    if (!flow.get("rainbow_running")) {
        return null;
    }
    let index = flow.get("rainbow_index") || 0;
    const c = rainbow[index];
    flow.set("rainbow_index", (index + 1) % rainbow.length);
    return sendColor("Rainbow: " + c.name, c.hue, c.saturation, 180, 1.5);
}

if (cmd === "chill") {
    flow.set("rainbow_running", false);
    return sendWhite("Chill warm", 370, 120, 1);
}

if (cmd === "bath_bright") {
    flow.set("rainbow_running", false);
    return sendWhite("Bad hell", 250, 254, 0.5);
}

if (cmd === "night") {
    flow.set("rainbow_running", false);
    return sendColor("Nachtmodus", 30, 100, 25, 1);
}

if (cmd === "cyberpunk") {
    flow.set("rainbow_running", false);
    return sendColor("Cyberpunk", 285, 100, 200, 1);
}

if (cmd === "alarm") {
    flow.set("rainbow_running", false);
    return sendColor("Alarm rot", 0, 100, 254, 0.2);
}

if (cmd === "candle") {
    flow.set("rainbow_running", false);
    return sendColor("Kerze", 28, 100, 70, 2);
}

if (cmd === "party") {
    flow.set("rainbow_running", false);
    const hues = [0, 300, 220, 120, 40];
    const randomHue = hues[Math.floor(Math.random() * hues.length)];
    return sendColor("Party", randomHue, 100, 254, 0.1);
}

node.status({ fill: "red", shape: "ring", text: "unbekannt: " + cmd });
return null;

