const RAINBOW_BRIGHTNESS = 170;
const RAINBOW_SATURATION = 100;
const RAINBOW_HUE_STEP = 4;       // kleiner = ruhiger, größer = schneller/fetziger
const RAINBOW_TRANSITION = 1.2;   // sollte ungefähr zum Timing passen

const BLUE_NIGHT_HUE = 235;
const BLUE_NIGHT_SATURATION = 100;
const BLUE_NIGHT_BRIGHTNESS = 35; // 1-254

const CANDLE_HUE_MIN = 22;
const CANDLE_HUE_MAX = 38;
const CANDLE_BRIGHTNESS_MIN = 35;
const CANDLE_BRIGHTNESS_MAX = 95;
const CANDLE_TRANSITION_MIN = 0.15;
const CANDLE_TRANSITION_MAX = 0.8;

function randomBetween(min, max) {
    return min + Math.random() * (max - min);
}

function randomInt(min, max) {
    return Math.round(randomBetween(min, max));
}

function stopAnimations() {
    flow.set("rainbow_running_v2", false);
    flow.set("candle_running_v2", false);
}

function sendColor(label, hue, saturation, brightness, transition) {
    msg.payload = {
        state: "ON",
        brightness: brightness,
        color: {
            hue: hue,
            saturation: saturation
        },
        transition: transition
    };
    node.status({ fill: "blue", shape: "dot", text: label });
    return msg;
}

function sendWhite(label, colorTemp, brightness, transition) {
    msg.payload = {
        state: "ON",
        brightness: brightness,
        color_temp: colorTemp,
        transition: transition
    };
    node.status({ fill: "yellow", shape: "dot", text: label });
    return msg;
}

if (cmd === "rainbow_start") {
    flow.set("candle_running_v2", false);
    flow.set("rainbow_running_v2", true);

    let hue = flow.get("rainbow_hue_v2");
    if (typeof hue !== "number") hue = 0;

    return sendColor("Rainbow läuft", hue, RAINBOW_SATURATION, RAINBOW_BRIGHTNESS, RAINBOW_TRANSITION);
}

if (cmd === "rainbow_stop") {
    flow.set("rainbow_running_v2", false);
    node.status({ fill: "grey", shape: "ring", text: "Rainbow aus" });
    return null;
}

if (cmd === "rainbow_tick") {
    if (!flow.get("rainbow_running_v2")) return null;

    let hue = flow.get("rainbow_hue_v2");
    if (typeof hue !== "number") hue = 0;

    hue = (hue + RAINBOW_HUE_STEP) % 360;
    flow.set("rainbow_hue_v2", hue);

    return sendColor("Rainbow hue " + Math.round(hue), hue, RAINBOW_SATURATION, RAINBOW_BRIGHTNESS, RAINBOW_TRANSITION);
}

if (cmd === "blue_night") {
    stopAnimations();
    return sendColor("Blauer Nachtmodus", BLUE_NIGHT_HUE, BLUE_NIGHT_SATURATION, BLUE_NIGHT_BRIGHTNESS, 1.5);
}

if (cmd === "candle_start") {
    flow.set("rainbow_running_v2", false);
    flow.set("candle_running_v2", true);
    return sendColor("Kerze startet", 30, 100, 65, 0.3);
}

if (cmd === "candle_stop") {
    flow.set("candle_running_v2", false);
    node.status({ fill: "grey", shape: "ring", text: "Kerze aus" });
    return null;
}

if (cmd === "candle_tick") {
    if (!flow.get("candle_running_v2")) return null;

    const hue = randomInt(CANDLE_HUE_MIN, CANDLE_HUE_MAX);
    const brightness = randomInt(CANDLE_BRIGHTNESS_MIN, CANDLE_BRIGHTNESS_MAX);
    const transition = randomBetween(CANDLE_TRANSITION_MIN, CANDLE_TRANSITION_MAX);

    return sendColor("Kerze " + brightness, hue, 100, brightness, transition);
}

if (cmd === "bath_bright") {
    stopAnimations();
    return sendWhite("Bad hell", 250, 254, 0.5);
}

if (cmd === "off") {
    stopAnimations();
    msg.payload = { state: "OFF" };
    node.status({ fill: "grey", shape: "ring", text: "aus" });
    return msg;
}

node.status({ fill: "red", shape: "ring", text: "unbekannt: " + cmd });
return null;

flow.set("lamp_auto_enabled", true);

if (flow.get("daytime_is_day") === true) {
    msg.payload = { cmd: "bath_bright" };
    node.status({ fill: "yellow", shape: "dot", text: "Tag -> Bad Hell" });
    return [null, msg];
}

