const payload = msg.payload;
const topic = String(msg.topic || msg.event || (payload && payload.event) || "").toLowerCase();
let isDay;

// Preserve the old intended mapping: payload "0" -> day, payload "1" -> night.
if (payload === 0 || payload === "0") {
    isDay = true;
} else if (payload === 1 || payload === "1") {
    isDay = false;
} else if (payload === true || payload === "day" || payload === "daytime" || payload === "sunrise") {
    isDay = true;
} else if (payload === false || payload === "night" || payload === "nighttime" || payload === "sunset") {
    isDay = false;
} else if (topic.includes("sunrise") || topic.includes("start")) {
    isDay = true;
} else if (topic.includes("sunset") || topic.includes("end")) {
    isDay = false;
} else {
    node.warn("Unknown Day/Night payload: " + JSON.stringify(payload));
    return null;
}

flow.set("daytime_is_day", isDay);
msg.payload = { state: isDay ? "ON" : "OFF" };

node.status({
